 func testEncryptedStorePersistsPendingOperationsAndRejectsWrongKey()throws{let dir=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString);defer{try? FileManager.default.removeItem(at:dir)};let key=Data(repeating:7,count:32),file=try EncryptedFile(url:dir.appendingPathComponent("state.bin"),key:key);var a=AppState();var s=try state();s.pending=["requestId":"private-pending-delivery"];a.companies["soboce"]=s;try file.save(a);XCTAssertEqual(try file.load().companies["soboce"]?.pending,s.pending);XCTAssertFalse(String(decoding:try Data(contentsOf:file.url),as:UTF8.self).contains("private-pending-delivery"));XCTAssertThrowsError(try EncryptedFile(url:file.url,key:Data(repeating:8,count:32)).load())}
